<?php
if (!defined('ABSPATH')) { exit; }
function emdo27_words($html){$text=trim(preg_replace('/\s+/u',' ',wp_strip_all_tags(strip_shortcodes($html))));if($text==='')return 0;preg_match_all('/[\p{L}\p{M}]+(?:[’\x{27}’-][\p{L}\p{M}]+)*/u',$text,$m);return count($m[0]);}
function emdo27_cat($name,$slug,$en_name,$en_slug){$term=get_term_by('slug',$slug,'category');if(!$term){$made=wp_insert_term($name,'category',array('slug'=>$slug));if(is_wp_error($made))throw new Exception($made->get_error_message());$term=get_term((int)$made['term_id'],'category');}update_term_meta($term->term_id,'_en_US_name',$en_name);update_term_meta($term->term_id,'_en_US_slug',$en_slug);update_term_meta($term->term_id,'_en_US_published','1');return (int)$term->term_id;}
function emdo27_existing($key,$slug){$ids=get_posts(array('post_type'=>'post','post_status'=>'any','posts_per_page'=>1,'fields'=>'ids','meta_key'=>'_emdo_authority_key','meta_value'=>$key));if($ids)return (int)$ids[0];$p=get_page_by_path($slug,OBJECT,'post');return $p?(int)$p->ID:0;}
function emdo27_product_slug($topic){$map=array('preserves'=>array(array('conservas','conservas-vegetales','conservas-y-encurtidos'),array('Conservas','Conservas vegetales','Preserves')),'hams'=>array(array('jamones-y-paletas','jamones-paletas','jamones'),array('Jamones y paletas','Jamones y Paletas','Hams and shoulders')));if(!isset($map[$topic]))throw new Exception('Unknown product topic '.$topic);foreach($map[$topic][0] as $slug){$t=get_term_by('slug',$slug,'product_cat');if($t)return $t->slug;}foreach($map[$topic][1] as $name){$t=get_term_by('name',$name,'product_cat');if($t)return $t->slug;}$search=$topic==='preserves'?'conserv':'jam';$terms=get_terms(array('taxonomy'=>'product_cat','hide_empty'=>false,'search'=>$search,'number'=>20));if(!is_wp_error($terms)){foreach($terms as $t){$n=remove_accents(strtolower($t->name));$s=strtolower($t->slug);if($topic==='preserves'&&(strpos($n,'conserv')!==false||strpos($s,'conserv')!==false))return $t->slug;if($topic==='hams'&&(strpos($n,'jamon')!==false||strpos($s,'jamon')!==false))return $t->slug;}}throw new Exception('Product category not found for '.$topic);}
$dir=(string)getenv('EMDO_BATCH27_CORE_DIR');if(!$dir||!is_dir($dir))throw new Exception('Batch 27 data directory missing');$files=glob(trailingslashit($dir).'*.php');sort($files,SORT_NATURAL);if(count($files)!==4)throw new Exception('Expected four article files');
$guide=emdo27_cat('Guías y consejos','guias-y-consejos','Guides and advice','guides-and-advice');$preserves=emdo27_cat('Conservas','conservas','Preserves','preserves');$hams=emdo27_cat('Jamones y paletas','jamones-y-paletas','Hams and shoulders','hams-and-shoulders');$cats=array('preserves'=>$preserves,'hams'=>$hams);
$preserves_product=emdo27_product_slug('preserves');$hams_product=emdo27_product_slug('hams');$default=(int)get_option('emdo_default_blog_featured_attachment_id',0);if($default<=0||get_post_type($default)!=='attachment')throw new Exception('Central provisional image missing');$default_hash=(string)get_option('emdo_default_blog_featured_hash','');$admins=get_users(array('role'=>'administrator','number'=>1,'fields'=>'ID'));$author=$admins?(int)$admins[0]:1;$rows=array();
foreach($files as $file){$a=require $file;foreach(array('key','slug','en_slug','topic','title','en_title','excerpt','en_excerpt','content','en_content') as $f){if(empty($a[$f]))throw new Exception(basename($file).' missing '.$f);}if(!isset($cats[$a['topic']]))throw new Exception('Unexpected topic '.$a['topic']);$repl=array('__PRESERVES__'=>$preserves_product,'__HAMS__'=>$hams_product);$content=strtr($a['content'],$repl);$en=strtr($a['en_content'],$repl);$wes=emdo27_words($content);$wen=emdo27_words($en);if($wes<850||$wen<750)throw new Exception($a['key'].' too short ES='.$wes.' EN='.$wen);$existing=emdo27_existing($a['key'],$a['slug']);$new=$existing<=0;$post=array('post_type'=>'post','post_status'=>'publish','post_author'=>$author,'post_title'=>wp_strip_all_tags($a['title']),'post_name'=>sanitize_title($a['slug']),'post_excerpt'=>wp_strip_all_tags($a['excerpt']),'post_content'=>$content);if($existing)$post['ID']=$existing;$res=$existing?wp_update_post($post,true):wp_insert_post($post,true);if(is_wp_error($res))throw new Exception($a['key'].': '.$res->get_error_message());$id=(int)$res;wp_set_post_categories($id,array($guide,$cats[$a['topic']]),false);update_post_meta($id,'_emdo_authority_key',$a['key']);update_post_meta($id,'_emdo_authority_batch','27');update_post_meta($id,'_en_US_post_title',wp_strip_all_tags($a['en_title']));update_post_meta($id,'_en_US_post_name',sanitize_title($a['en_slug']));update_post_meta($id,'_en_US_post_excerpt',wp_strip_all_tags($a['en_excerpt']));update_post_meta($id,'_en_US_post_content',$en);update_post_meta($id,'_en_US_ready','1');update_post_meta($id,'_en_US_published','1');update_post_meta($id,'_emdo_editorial_updated',gmdate('c'));$current=(int)get_post_thumbnail_id($id);$marked=(string)get_post_meta($id,'_emdo_uses_default_featured',true)==='1';if($new||$marked||$current<=0){update_post_meta($id,'_thumbnail_id',$default);update_post_meta($id,'_emdo_uses_default_featured','1');update_post_meta($id,'_emdo_editorial_image_approved_id',$default);delete_post_meta($id,'_emdo_editorial_image_approved_pexels_id');update_post_meta($id,'_emdo_editorial_cover_asset_id','emdo-blog-default-featured');update_post_meta($id,'_emdo_editorial_cover_brand_safe','1');update_post_meta($id,'_emdo_default_featured_hash',$default_hash);update_post_meta($id,'_emdo_default_featured_updated_at',gmdate('c'));}clean_post_cache($id);$rows[]=array('key'=>$a['key'],'id'=>$id,'status'=>get_post_status($id),'slug'=>get_post_field('post_name',$id),'en_slug'=>sanitize_title($a['en_slug']),'thumbnail_id'=>(int)get_post_thumbnail_id($id),'provisional'=>(string)get_post_meta($id,'_emdo_uses_default_featured',true),'words_es'=>$wes,'words_en'=>$wen,'topic'=>$a['topic'],'product_category'=>$a['topic']==='preserves'?$preserves_product:$hams_product);}
if(count($rows)!==4)throw new Exception('Publish count mismatch');echo wp_json_encode(array('batch'=>27,'default'=>$default,'posts'=>$rows),JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES|JSON_PRETTY_PRINT).PHP_EOL;
